async function physician360(npiRaw: string, stateRaw = '', ccnRaw = '') { const npi = normalizePhysicianNpi(npiRaw); if (!npi) throw new Error('Physician NPI must be 10 digits.'); const path = `cms-cache/physician-360-v2/${npi}.json`, fresh = await readJsonCache<any>(path, 4 * 3600000); let base = fresh?.data as any; if (!base) { const [profileR,servicesR,orderR] = await Promise.all([safe('Physician profile', () => mainQuery(MAIN.physicians, { filters: { Rndrng_NPI: npi }, size: 25 })), safe('Provider + Service', () => pagedMain(MAIN.physicianServices, { Rndrng_NPI: npi }, 10000)), safe('Order and Referring', () => mainQuery(MAIN.orderReferring, { filters: { NPI: npi }, size: 25 }))]), profileRows = profileR.ok ? profileR.data.rows as Row[] : [], profile = profileRows.length ? physicianFrom(profileRows[0]) : null, serviceRows = servicesR.ok ? servicesR.data.rows as Row[] : [], services = serviceRows.map((r) => ({ hcpcs: txt(val(r,'HCPCS_Cd','HCPCS_CD')), description: txt(val(r,'HCPCS_Desc','HCPCS_DESCRIPTION')), placeOfService: txt(val(r,'Place_Of_Srvc','PLACE_OF_SERVICE')), beneficiaries: maybeNumber(val(r,'Tot_Benes','TOTAL_BENEFICIARIES')), services: maybeNumber(val(r,'Tot_Srvcs','TOTAL_SERVICES')), averageMedicarePayment: maybeNumber(val(r,'Avg_Mdcr_Pymt_Amt','AVERAGE_MEDICARE_PAYMENT_AMOUNT')), drugIndicator: txt(val(r,'HCPCS_Drug_Ind')) })).sort((a,b) => (b.services ?? -1) - (a.services ?? -1)), order = orderR.ok ? orderR.data.rows[0] || {} : {}, flag = (name: string) => { const raw = txt(val(order,name)); return { raw: raw || 'NR', eligible: /^y(es)?$/i.test(raw) }; }; if (!profile && !services.length && (!orderR.ok || !orderR.data.rows.length)) throw new Error(`No current CMS physician intelligence was resolved for NPI ${npi}.`); base = { npi, profile, eligibility: { partB: flag('PARTB'), dme: flag('DME'), hha: flag('HHA'), pmd: flag('PMD'), hospice: flag('HOSPICE') }, summary: { serviceRows: services.length, totalServices: reportedSum(services.map((s) => s.services)).value }, services: services.slice(0,100), warnings: [!profileR.ok?profileR.error:'',!servicesR.ok?servicesR.error:'',!orderR.ok?orderR.error:''].filter(Boolean), caveat: 'CMS Order and Referring reports Medicare eligibility to order/refer. It does not show that this clinician actually referred a patient to this hospice.' }; await writeJsonCache(path, base); } const state = normalizeState(stateRaw || base.profile?.state || 'OK'); let rankedMatch: any = null, marketContext = null; try { const ranked = await physiciansForState(state, ccnRaw); rankedMatch = ranked.physicians.find((row: any) => row.npi === npi) || null; marketContext = rankedMatch ? { ...(ranked.marketContext || {}), countyFips: rankedMatch.countyFips || '', county: rankedMatch.county || '', countyApproximation: Boolean(rankedMatch.countyApproximation), multiCountyZcta: Boolean(rankedMatch.multiCountyZcta), inServiceArea: Boolean(rankedMatch.inServiceArea) } : ranked.marketContext; } catch {} const profile = rankedMatch && base.profile ? { ...base.profile, ...rankedMatch } : base.profile; return { ...base, profile, ranking: rankedMatch ? { score: rankedMatch.score, evidenceScore: rankedMatch.evidenceScore, scoreCoveragePct: rankedMatch.scoreCoveragePct, conditionCoveragePct: rankedMatch.conditionCoveragePct, peerGroup: rankedMatch.peerGroup, peerGroupSize: rankedMatch.peerGroupSize, volumePercentile: rankedMatch.volumePercentile, seriousIllnessPercentile: rankedMatch.seriousIllnessPercentile, serviceIntensityPercentile: rankedMatch.serviceIntensityPercentile, modelVersion: rankedMatch.modelVersion, scoreBasis: rankedMatch.scoreBasis } : null, marketContext, cache: fresh ? { mode: 'persistent', ageMinutes: fresh.ageMinutes } : { mode: 'refreshed', ageMinutes: 0 } }; }
async function observedCapabilities(ccnRaw: string, deep = false) { const id = normalizeCcn(ccnRaw), detail = await providerDetail(id); let hcris: any = null; try { hcris = await getHcrisIntelligence(id, deep, false); } catch {} return buildObservedCapabilities(detail, hcris); }
async function territoryDeployment(ccnRaw: string, stateRaw: string) { const id = normalizeCcn(ccnRaw), state = normalizeState(stateRaw), [market,geo] = await Promise.all([dashboard(state,id,false), getServiceGeography(id,false)]), adj = await getCountyAdjacency((market.counties || []).map((c: any) => String(c.fips || '')).filter(Boolean), false); return { ...buildTerritoryDeploymentV3(market.counties || [], geo, adj.adjacency || {}), state, stateName: STATE_NAMES[state], adjacency: { source: adj.source, schemaHealth: adj.schemaHealth, countyCount: adj.countyCount } }; }
async function privateTerritoryDeployment(userId: string, ccnRaw: string, stateRaw: string) { const deployment = await territoryDeployment(ccnRaw,stateRaw), truth = await listOperationalTruth(userId,ccnRaw); return { ...applyOperationalTruth(deployment,truth.records), operationalTruthWarning: truth.warning || '' }; }
async function hcrisRoutingStatus(ccnRaw: string) { const id = normalizeCcn(ccnRaw), [detail,hcris] = await Promise.all([providerDetail(id), getHcrisIntelligence(id,false,false)]), providerType = txt(detail.provider?.type) || 'Not reported', normalized = providerType.toLowerCase(), explicitFreestanding = /freestanding/.test(normalized), parentRoute = resolveParentFormRoute(providerType); if (hcris?.available) return { ccn:id,providerType,status:'FREESTANDING MODEL AVAILABLE',deepModelAvailable:true,controllingForm:'CMS-1984-14',nextStep:'The validated freestanding hospice operating model can be loaded for this provider.' }; if (parentRoute) return { ccn:id,providerType,status:parentRoute.status,deepModelAvailable:true,controllingForm:parentRoute.parentForm,providerBasis:parentRoute.providerBasis,nextStep:parentRoute.nextStep,normalization:'parent-form-routed' }; if (explicitFreestanding) return { ccn:id,providerType,status:'FREESTANDING REPORT NOT RESOLVED',deepModelAvailable:false,controllingForm:'CMS-1984-14 expected but report not resolved',nextStep:'Recheck the hospice cost-report release and provider number. No synthetic operating model is created.' }; return { ccn:id,providerType,status:'FORM UNRESOLVED',deepModelAvailable:false,controllingForm:'Not established from current public evidence',nextStep:'Keep financial depth scoped until the controlling cost-report form is validated.' }; }

const winLossTable = (userId: string, providerCcn: string) => `winloss:${userId}:${normalizeCcn(providerCcn)}`;
function clip(v: unknown, max: number) { return txt(v).slice(0,max); }
function winLossSummary(records: Array<WinLossRecord & { id: string }>) { const wins = records.filter((r) => r.outcome === 'Win'), losses = records.filter((r) => r.outcome === 'Loss'), top = (rows: Array<WinLossRecord & {id:string}>, field: 'competitor'|'reason') => { const counts = new Map<string,number>(); rows.forEach((r) => { const value = clip(r[field],120) || 'Unknown'; counts.set(value,(counts.get(value)||0)+1); }); return [...counts.entries()].sort((a,b) => b[1]-a[1])[0]?.[0] || 'Not enough data'; }; return { total:records.length,wins:wins.length,losses:losses.length,winRate:records.length?Math.round(wins.length/records.length*1000)/10:0,topLossCompetitor:top(losses,'competitor'),topLossReason:top(losses,'reason'),topWinReason:top(wins,'reason'),estimatedMonthlyWon:wins.reduce((a,r)=>a+(Number(r.estimatedMonthlyReferrals)||0),0) }; }
async function listWinLoss(userId: string, providerCcn: string) { const page = await db.list<WinLossRecord>(winLossTable(userId,providerCcn), { limit:500 }), records = page.items.sort((a,b) => `${b.date}${b.createdAt}`.localeCompare(`${a.date}${a.createdAt}`)); return { records, summary: winLossSummary(records), truncated: Boolean(page.nextToken), warning: page.nextToken ? 'This hospice has more than 500 stored decisions. The current view shows the newest page.' : '' }; }
function winLossPayload(body: unknown, existing?: WinLossRecord) { const b = (body && typeof body === 'object' ? body : {}) as Record<string,unknown>, outcome = clip(b.outcome,10), account = clip(b.account,140), providerCcn = clip(b.providerCcn,10) || existing?.providerCcn || ''; if (!providerCcn) return { error:'Provider CCN is required' }; if (outcome !== 'Win' && outcome !== 'Loss') return { error:'Outcome must be Win or Loss' }; if (!account) return { error:'Account is required' }; return { record: { providerCcn, date: clip(b.date,10) || new Date().toISOString().slice(0,10), outcome: outcome as 'Win'|'Loss', account, accountType: clip(b.accountType,60) || 'Other', county: clip(b.county,80), competitor: clip(b.competitor,160), reason: clip(b.reason,120) || 'Other', notes: clip(b.notes,1000), estimatedMonthlyReferrals: Math.max(0,Math.min(999,number(b.estimatedMonthlyReferrals))), createdAt: existing?.createdAt || new Date().toISOString() } satisfies WinLossRecord }; }

export const intelligenceOperationsHandler = async (event: { payload?: { limit?: number } }) => { const record: any = { checkedAt:new Date().toISOString(),processed:0,changed:0,failed:0 }; try { const monitor = await processWatchedProviderBatch(event.payload?.limit || 4); Object.assign(record,{processed:monitor.processed,changed:monitor.changed,failed:monitor.failed,more:monitor.nextToken,pending:monitor.pending}); } catch (e) { record.failed = 1; record.error = errText(e); } try { await db.add('monitor-runs',[record]); } catch {} return { statusCode:200 }; };
export const sourceHealthHandler = async () => { const record: any = { checkedAt:new Date().toISOString(),overall:'unknown' }; try { const health = await getSourceHealth(true); Object.assign(record,{checkedAt:health.checkedAt,overall:health.overall,changedSources:health.changedSources||[]}); } catch (e) { record.overall='error';record.error=errText(e); } try { await db.add('source-health-runs',[record]); } catch {} return { statusCode:200 }; };
export const physicianWarehouseHandler = async () => { const record: any = { checkedAt:new Date().toISOString(),status:'unknown' }; try { const seed = await seedNationalPhysicianWarehouse(), step = await processPhysicianWarehouseStep(1); Object.assign(record,{status:step?.status?.status||'building',seeded:Boolean(seed?.seeded),sourceVersion:seed?.sourceVersion||'',states:step?.states||0,failed:step?.failed||0}); } catch (e) { record.status='error';record.error=errText(e); } try { await db.add('physician-warehouse-runs',[record]); } catch {} return { statusCode:200 }; };
export const competitionWarehouseHandler = async () => { const record: any = { checkedAt:new Date().toISOString(),status:'unknown' }; try { const seed = await seedNationalCompetitionWarehouse(), step = await processCompetitionWarehouseStep(1); Object.assign(record,{status:step?.status?.status||seed?.status||'queued',seeded:Boolean(seed),sourceVersion:seed?.sourceVersion||'',rowsProcessed:step?.status?.rowsProcessed||0,failed:step?.status?.status==='error'?1:0}); } catch (e) { record.status='error';record.error=errText(e); } try { await db.add('competition-warehouse-runs',[record]); } catch {} return { statusCode:200 }; };
async function systemDiagnostics(stateRaw: string, ccnRaw: string) { const state = normalizeState(stateRaw || 'OK'), id = normalizeCcn(ccnRaw), checks: any[] = []; for (const [label,fn] of [['Market',()=>dashboard(state,id,false)],['Provider Detail',()=>providerDetail(id)],['Provider 360',()=>buildAdvancedIntelligence(id,state,false)],['SSVI',()=>getSsviIntelligence(id,false)],['HCRIS',()=>getHcrisIntelligence(id,false,false)],['Service Geography',()=>getServiceGeography(id,false)],['Source Health',()=>getSourceHealth(false)],['Competition Warehouse',()=>getCompetitionCoverageStatus()]] as Array<[string,()=>Promise<any>]>) { const at=Date.now(); try { const data=await fn(), status=data?.dataQuality?.status==='degraded'||data?.schemaHealth==='unavailable'?'error':data?.dataQuality?.status==='limited'||data?.schemaHealth==='limited'||data?.nationallyComplete===false?'limited':'healthy'; checks.push({label,status,ms:Date.now()-at,cacheMode:data?.cache?.mode||data?.mode||'live',stale:data?.cache?.mode==='stale-fallback',detail:data?.cache?.refreshError||data?.error||data?.caveat||''}); } catch (e) { checks.push({label,status:'error',ms:Date.now()-at,cacheMode:'failed',stale:false,detail:errText(e)}); } } let sourceHealth:any=null,monitoring:any=null,physicianWarehouse:any=null,competitionWarehouse:any=null; try { const [s,m,p,c]=await Promise.all([db.list<any>('source-health-runs',{limit:20}),db.list<any>('monitor-runs',{limit:20}),db.list<any>('physician-warehouse-runs',{limit:20}),db.list<any>('competition-warehouse-runs',{limit:20})]); sourceHealth=s.items.sort((a,b)=>String(b.checkedAt||'').localeCompare(String(a.checkedAt||'')))[0]||null; monitoring=m.items.sort((a,b)=>String(b.checkedAt||'').localeCompare(String(a.checkedAt||'')))[0]||null; physicianWarehouse=p.items.sort((a,b)=>String(b.checkedAt||'').localeCompare(String(a.checkedAt||'')))[0]||null; competitionWarehouse=c.items.sort((a,b)=>String(b.checkedAt||'').localeCompare(String(a.checkedAt||'')))[0]||null; } catch {} const overall = checks.some((c) => c.status === 'error') ? 'degraded' : checks.some((c) => c.status === 'limited') ? 'limited' : 'healthy'; return { checkedAt:new Date().toISOString(),state,ccn:id,overall,checks,scheduled:{sourceHealth,monitoring,physicianWarehouse,competitionWarehouse} }; }

